def select(self, population: list, k: int) -> list:
    """MODEA: Tournament selection with adaptive reference guidance.

    Uses dominance comparison enhanced by reference vector alignment to
    guide tournament selection, balancing exploitation of known good
    solutions with exploration of reference-guided regions.
    """
    selected = []
    for _ in range(k):
        i1, i2 = random.sample(range(len(population)), 2)
        ind1, ind2 = population[i1], population[i2]

        if ind1.fitness.valid and ind2.fitness.valid:
            if ind1.fitness.values < ind2.fitness.values:
                ind1_dom = True
                ind2_dom = False
            elif ind2.fitness.values < ind1.fitness.values:
                ind1_dom = False
                ind2_dom = True
            else:
                # Tie-break: use reference guidance
                # Calculate projected alignment with ref_points
                ref_vecs = np.array(self.ref_points) if len(self.ref_points) > 0 else []
                if len(ref_vecs) > 0:
                    f1 = np.array(ind1.fitness.values)
                    f2 = np.array(ind2.fitness.values)
                    # Simple tie-break by lexicographic order
                    if tuple(f1) < tuple(f2):
                        ind1_dom = True
                    else:
                        ind1_dom = False
                else:
                    ind1_dom = random.random() < 0.5
        else:
            # One or both are unevaluated, use random preference
            ind1_dom = random.random() < 0.5
            ind2_dom = random.random() < 0.5

        # Select based on dominance
        if ind1_dom:
            selected.append(deepcopy(ind1))
        if ind2_dom and (not ind1_dom or ind2_dom and random.random() < 0.5):
            selected.append(deepcopy(ind2))

    return selected

def vary(self, parents: list) -> list:
    """MODEA: Standard SBX crossover + polynomial mutation.

    Uses standard DEAP operators for recombination.
    """
    offspring = [deepcopy(ind) for ind in parents]
    lo, hi = self.bounds

    # SBX crossover with 90% probability
    for i in range(0, len(offspring) - 1, 2):
        if random.random() < 0.9:
            tools.cxSimulatedBinaryBounded(
                offspring[i], offspring[i + 1],
                eta=self.cx_eta, low=lo, up=hi,
            )
            del offspring[i].fitness.values
            del offspring[i + 1].fitness.values

    # Polynomial mutation
    for ind in offspring:
        if random.random() < 1.0:
            tools.mutPolynomialBounded(
                ind, eta=self.mut_eta, low=lo, up=hi, indpb=self.mut_prob,
            )
            del ind.fitness.values

    return offspring

