    """MODEA-i: Tournament selection based on Pareto dominance hierarchy.

    Selects k individuals using binary tournament, comparing criterion
    values to select the better individual when fitnesses are valid.
    """
    from copy import deepcopy

    selected = []
    for _ in range(k):
        i1, i2 = random.sample(range(len(population)), 2)
        if population[i1].fitness.valid and population[i2].fitness.valid:
            # Use tournament selection with dominance comparison
            better = None
            for j in range(self.n_obj):
                if population[i1].fitness.values[j] < population[i2].fitness.values[j]:
                    better = i1
                    break
                if population[i2].fitness.values[j] < population[i1].fitness.values[j]:
                    better = i2
                    break
            if better is None:
                better = random.choice([i1, i2])
        else:
            best = None
            for j in range(self.n_obj):
                if population[i1].fitness.values[j] >= float('inf'):
                    best = i2
                    break
                if population[i2].fitness.values[j] >= float('inf'):
                    best = i1
                    break
            if best is None:
                best = i1

            if population[i1].fitness.values[0] < float('inf') and population[i2].fitness.values[0] < float('inf'):
                best = i1

            if population[i2].fitness.values[0] < population[i1].fitness.values[0]:
                best = i2

            if better is None:
                selected.append(deepcopy(population[i1]))
            else:
                selected.append(deepcopy(population[better]))
            continue

        if population[i1].fitness.values[0] == population[i2].fitness.values[0]:
            selected.append(deepcopy(population[i1]))
        else:
            selected.append(deepcopy(population[i2]))

    return selected

