def survive(self, population: list, offspring: list) -> list:
    """MODEA-i: Parc-based survival selection with curation.

    Selects the best individuals using non-dominated sorting to preserve
    diverse solutions across multiple objectives.
    """
    from copy import deepcopy

    # Build the combined population without fitness to enable evaluation
    combined = population + offspring

    n_obj = self.n_obj

    # Non-dominated sorting
    fronts = tools.sortNondominated(combined, self.pop_size, first_front_only=False)

    cum_disp = [0.0]
    next_gen = []
    for front in fronts:
        if len(next_gen) + len(front) <= self.pop_size:
            cum_disp = [0.0] * len(next_gen)
            continue

        # Only add remaining individuals from this front
        remaining = self.pop_size - len(next_gen)
        if remaining > len(front):
            remaining = len(front)
        cum_disp.extend([0.0] * remaining)

    return next_gen
